b<-'.';o<-file.path(b,'NHANES_TB_Stage3_Inference_Audit_20261116');.libPaths(c(file.path(b,'TB_metabolome_exposome_20261115_2130/analysis_MWAS_ExWAS/Rlib'),.libPaths()));library(survey);z<-readRDS(file.path(o,'数据/rebuilt_private.rds'));s<-z$domain;f<-z$fit;X<-model.matrix(f);pr<-fitted(f);w<-s$variables$WTMEC2YR;w<-w/mean(w);sc<-X*as.numeric(w*(s$variables$y-pr));H<-crossprod(X,X*as.numeric(w*pr*(1-pr)));u<-rowsum(sc,interaction(s$variables$SDMVSTRA,s$variables$SDMVPSU,drop=TRUE));ps<-unique(s$variables[,c('SDMVSTRA','SDMVPSU')]);key<-as.character(interaction(ps$SDMVSTRA,ps$SDMVPSU,drop=TRUE));u<-u[key,,drop=FALSE];M<-matrix(0,ncol(X),ncol(X));for(h in unique(ps$SDMVSTRA)){uh<-u[ps$SDMVSTRA==h,,drop=FALSE];m<-nrow(uh);if(m>1){uc<-sweep(uh,2,colMeans(uh));M<-M+crossprod(uc)*m/(m-1)}};V<-solve(H)%*%M%*%solve(H);write.csv(data.frame(method=c('survey','independent_stratum_PSU_sandwich'),se=c(sqrt(vcov(f)['x','x']),sqrt(V['x','x']))),file.path(o,'数据/11_独立方差核验.csv'),row.names=FALSE)
